SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.discharge_location, a.dod, a.los, COUNT(*)::FLOAT / NULLIF(COUNT(CASE WHEN a.dod <= 10 THEN 1 END), 0) AS proportion_of_patients_with_dod_leq_10_days FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 50 AND 60 AND a.admission_type = 'ED' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.discharge_location, a.dod, a.los ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.discharge_location, a.dod, a.los NULLS LAST;